def test_non_finite_device_output_never_passes_the_gate():
    ref = gram64(counter_normals(3, 4, 500))
    bad = ref.copy()
    bad[0, 1] = np.nan
    assert max_rel_err(bad, ref) == float("inf")
    assert not max_rel_err(bad, ref) <= REL_TOL
    assert max(0.0, max_rel_err(bad, ref)) == float("inf")


def test_counter_normals_are_standard_normal_and_deterministic():
    z = counter_normals(7, 16, 20000)
    assert z.dtype == np.float32 and z.shape == (16, 20000)
    assert abs(float(z.mean())) < 0.005 and abs(float(z.var()) - 1.0) < 0.01
    assert np.array_equal(z, counter_normals(7, 16, 20000))
    assert not np.array_equal(z, counter_normals(8, 16, 20000))


def test_assemble_matches_explicit_products():
    rng = np.random.default_rng(0)
    roots = rng.standard_normal((5, 6, 6))
    grams = rng.standard_normal((5, 6, 6))
    out = assemble(roots, grams)
    for b in range(5):
        assert np.allclose(out[b], roots[b] @ grams[b] @ roots[b].T, rtol=1e-13, atol=1e-13)


def test_square_roots_reconstruct_the_spectra():
    rng = np.random.default_rng(1)
    a = rng.standard_normal((4, 8, 8))
    cl = a @ a.transpose(0, 2, 1) + 0.1 * np.eye(8)
    r = square_roots(cl)
    assert np.allclose(r @ r.transpose(0, 2, 1), cl, rtol=1e-11, atol=1e-12)


def test_numpy_fallback_draw_is_unbiased():
    rng = np.random.default_rng(2)
    a = rng.standard_normal((3, 6, 6))
    cl = a @ a.transpose(0, 2, 1) + np.eye(6)
    roots, dof = square_roots(cl), np.array([400, 800, 1600])
    draws = np.array([numpy_draw(roots, dof, rng) for _ in range(200)])
    z = (draws.mean(0) - cl) / (draws.std(0) / np.sqrt(200))
    d = np.diagonal(z, axis1=1, axis2=2)
    assert abs(d.mean()) < 0.4 and 0.6 < d.std() < 1.4


def test_attestation_is_present_and_covers_real_bin_sizes():
    assert ATTESTATION is not None, "run scripts/gpu_attest.py on the machine with the accelerators"
    assert ATTESTATION["rel_tol"] == REL_TOL
    dofs = [c["dof"] for c in ATTESTATION["cases"]]
    assert len(dofs) == 3 and max(dofs) > 20000  # includes the largest Planck bins
    assert "xpu" in ATTESTATION["devices"]


def test_device_grams_recomputed_in_float64():
    # For every recorded device: regenerate the exact normals, recompute Z Z^T / nu in float64,
    # and check the device's recorded error and its accept/reject decision.
    for name, rec in ATTESTATION["devices"].items():
        if rec["error"]:
            assert rec["accepted"] is False, name
            continue
        worst = 0.0
        for case, g in zip(ATTESTATION["cases"], rec["grams"]):
            z = counter_normals(case["seed"], ATTESTATION["nf"], case["dof"])
            worst = max(worst, max_rel_err(np.array(g), gram64(z)))
        if np.isfinite(worst):
            assert abs(worst - rec["max_rel_err"]) <= 1e-6 * max(worst, 1e-12) + 1e-12, name
        else:
            assert not np.isfinite(rec["max_rel_err"]), name
        assert rec["accepted"] == (worst <= REL_TOL), name


def test_gpu_is_accepted_and_did_its_own_float32_arithmetic():
    rec = ATTESTATION["devices"]["xpu"]
    worst = 0.0
    for case, g in zip(ATTESTATION["cases"], rec["grams"]):
        ref = gram64(counter_normals(case["seed"], ATTESTATION["nf"], case["dof"]))
        worst = max(worst, max_rel_err(np.array(g), ref))
    assert worst <= REL_TOL          # within the acceptance bound...
    assert worst > 1e-9              # ...and not a float64 copy: genuine float32 accumulation


def test_npu_is_measured_and_rejected_for_precision():
    # The NPU was run on the same normals; its reduced-precision result misses the float64
    # reference by more than REL_TOL, so the pipeline does not use it. Recomputed here.
    rec = ATTESTATION["devices"].get("npu")
    if rec is None or rec["error"]:  # NPU coverage is optional (see the note at the top)
        return
    worst = max(max_rel_err(np.array(g), gram64(counter_normals(c["seed"], ATTESTATION["nf"], c["dof"])))
                for c, g in zip(ATTESTATION["cases"], rec["grams"]))
    assert worst > REL_TOL
    assert rec["accepted"] is False
